		public ApplicationTest setHandler(Handler handler) {
			this.handler = handler;
			LOGGER.addHandler(handler); // assign so the LOGGER can only output results to the Handler
			return this;
		}

		/**
		 * Returns a new populated Application
		 * 
		 * @return Application
		 */
		protected Application generateNewEntity() {
			Application entity = new Application( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),   new Date(),  null,  null,  null,  new HashSet<>(),  null,  ApplicationStatus.values()[0] );
			
			return( entity );
		}

